Definition mk_0RB1RB_1LC1RA_0RA0LD_0LC0LD (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_0RB1RB_1LC1RA_0RA0LD_0LC0LD.

(** 0RB1RB_1LC1RA_0RA0LD_0LC0LD *)
(** 0RB1RB_1LC1RA_0RA0LD_0LC0LD -- the real machine (its counter grows RIGHT). *)
Definition tm_0RB1RB_1LC1RA_0RA0LD_0LC0LD : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S1 DR StB
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S1 DR StA
  | StC, S0 => mk S0 DR StA | StC, S1 => mk S0 DL StD
  | StD, S0 => mk S0 DL StC | StD, S1 => mk S0 DL StD end.

(** Its mirror 0LB1LB_1RC1LA_0LA0RD_0RC0RD: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB1RB_1LC1RA_0RA0LD_0LC0LD : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S1 DL StB
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DL StA
  | StC, S0 => mk S0 DL StA | StC, S1 => mk S0 DR StD
  | StD, S0 => mk S0 DR StC | StD, S1 => mk S0 DR StD end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB1RB_1LC1RA_0RA0LD_0LC0LD : list Instr := [].
Definition tmw_0RB1RB_1LC1RA_0RA0LD_0LC0LD : TM := tm_wrap_trs tmm_0RB1RB_1LC1RA_0RA0LD_0LC0LD pins_0RB1RB_1LC1RA_0RA0LD_0LC0LD.
Local Notation tm := tmw_0RB1RB_1LC1RA_0RA0LD_0LC0LD.

Lemma mirror_ok_0RB1RB_1LC1RA_0RA0LD_0LC0LD : mirror_tm tm_0RB1RB_1LC1RA_0RA0LD_0LC0LD = tmm_0RB1RB_1LC1RA_0RA0LD_0LC0LD.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

