    apply (lap_of_run tm Cc true true cho_0RB1RB_1LC1RA_0RA0LD_0LC1RD B0_0RB1RB_1LC1RA_0RA0LD_0LC1RD B1_0RB1RB_1LC1RA_0RA0LD_0LC1RD 10 18 p j' [] []).
