  - (* B1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB1RB_1LC1RA_1RD1LD_0RA0LC (StB, S1)).
    intros p1 j1 E1.
    exact (firex_0RB1RB_1LC1RA_1RD1LD_0RA0LC [SRotL 1; SWin 1; SCycL 2 0; SWin 1] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB1RB_1LC1RA_1RD1LD_0RA0LC (StC, S0)).
    intros p1 j1 E1.
    exact (firex_0RB1RB_1LC1RA_1RD1LD_0RA0LC [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 3] (StC, S0) ltac:(vm_compute; reflexivity)
