  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_0RB1RB_1LC1RA_1RD1LD_0RA0LC
      with (l := []).
    vm_compute; reflexivity.
  - (* D1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB1RB_1LC1RA_1RD1LD_0RA0LC (StD, S1)).
    intros p1 j1 E1.
    exact (firex_0RB1RB_1LC1RA_1RD1LD_0RA0LC [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 4] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
