Lemma gsi_0RB1RB_1LC1RB_0RA1LD_1RA0LC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_0RB1RB_1LC1RB_0RA1LD_1RA0LC.
