(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_0RB1RB_1RC0LD_1LD0RC_1LA0LA : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] 0 Z0_0RB1RB_1RC0LD_1LD0RC_1LA0LA /\
  lift (cden (Kp q0 ++ [S0]) [] 0 Z1_0RB1RB_1RC0LD_1LD0RC_1LA0LA) = lift (Cc (Pos.succ p)).
Proof.
