(** 0RB1RC_1LC0LC_0LD0RA_1RA1LD *)
Definition tm_0RB1RC_1LC0LC_0LD0RA_1RA1LD : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S1 DR StC
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S0 DL StC
  | StC, S0 => mk S0 DL StD | StC, S1 => mk S0 DR StA
  | StD, S0 => mk S1 DR StA | StD, S1 => mk S1 DL StD end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB1RC_1LC0LC_0LD0RA_1RA1LD : list Instr := [].
Definition tmw_0RB1RC_1LC0LC_0LD0RA_1RA1LD : TM := tm_wrap_trs tm_0RB1RC_1LC0LC_0LD0RA_1RA1LD pins_0RB1RC_1LC0LC_0LD0RA_1RA1LD.
