Lemma gen_0RB1RC_1LC0LC_0LD0RA_1RA1LD : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1]) [] i AI1_0RB1RC_1LC0LC_0LD0RA_1RA1LD) = lift (Cin (Pos.succ v)).
