Lemma lapin_0RB1RC_1LC0LC_0LD0RA_1RA1LD : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 12), (cden (Ip q0 ++ [S1]) [] i AI1_0RB1RC_1LC0LC_0LD0RA_1RA1LD).
  split; [lia|]. split; [| exact (gen_0RB1RC_1LC0LC_0LD0RA_1RA1LD v i q0 E)].
  rewrite (gsn_0RB1RC_1LC0LC_0LD0RA_1RA1LD v i q0 E).
  exact (srun_sound tm false true chn_0RB1RC_1LC0LC_0LD0RA_1RA1LD AI0_0RB1RC_1LC0LC_0LD0RA_1RA1LD AI1_0RB1RC_1LC0LC_0LD0RA_1RA1LD 4 12
           run_inner_0RB1RC_1LC0LC_0LD0RA_1RA1LD (Ip q0 ++ [S1]) [] i
