Definition B0_0RB1RD_0LC1RA_1RB1LC_0LC0LB : sconf := mkC StA (mkS [] [S1;S1;S1] 1 0 [S1;S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_0RB1RD_0LC1RA_1RB1LC_0LC0LB : sconf := mkC StA (mkS [] [S1;S1;S0] 1 1 [S1;S1;S1]) S0 (mkS [S0] [] 0 0 []).
(** ** The INNER anchor family -- Ap_Alph_110_111_1 at StC *)
Definition Cin_0RB1RD_0LC1RA_1RB1LC_0LC0LB (v : positive) : cconf := (StC, (Ap_Alph_110_111_1 v ++ [S1;S1], S0, [S1;S1])).
Local Notation Cin := Cin_0RB1RD_0LC1RA_1RB1LC_0LC0LB.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_0RB1RD_0LC1RA_1RB1LC_0LC0LB : forall n, Ap_Alph_110_111_1 (pow2 n) = rep [S1;S1;S0] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
