  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB1RD_0LC1RA_1RB1LC_0LD0RB p (pow2 j)).
  - exists (6 * j + 10), (cden [] [] j BB1_0RB1RD_0LC1RA_1RB1LC_0LD0RB).
    split; [lia|]. split; [| exact (gbo_0RB1RD_0LC1RA_1RB1LC_0LD0RB j)].
    rewrite (gso_0RB1RD_0LC1RA_1RB1LC_0LD0RB p j E).
    exact (srun_sound tm true true chb_0RB1RD_0LC1RA_1RB1LC_0LD0RB B0_0RB1RD_0LC1RA_1RB1LC_0LD0RB BB1_0RB1RD_0LC1RA_1RB1LC_0LD0RB 6 10
             run_boot_0RB1RD_0LC1RA_1RB1LC_0LD0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (6 * j + 13), (cden [] [] j B1_0RB1RD_0LC1RA_1RB1LC_0LD0RB).
    split; [| exact (geo_0RB1RD_0LC1RA_1RB1LC_0LD0RB p j E)].
    rewrite (gxi_0RB1RD_0LC1RA_1RB1LC_0LD0RB j).
    exact (srun_sound tm true true che_0RB1RD_0LC1RA_1RB1LC_0LD0RB BE0_0RB1RD_0LC1RA_1RB1LC_0LD0RB B1_0RB1RD_0LC1RA_1RB1LC_0LD0RB 6 13
             run_exit_0RB1RD_0LC1RA_1RB1LC_0LD0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_0RB1RD_0LC1RA_1RB1LC_0LD0RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB1RD_0LC1RA_1RB1LC_0LD0RB p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB1RD_0LC1RA_1RB1LC_0LD0RB p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_0RB1RD_0LC1RA_1RB1LC_0LD0RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 9.
  assert (H : match csteps tm 9 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 9 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB1RD_0LC1RA_1RB1LC_0LD0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB1RD_0LC1RA_1RB1LC_0LD0RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB1RD_0LC1RA_1RB1LC_0LD0RB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB1RD_0LC1RA_1RB1LC_0LD0RB p j E)].
Qed.


(** An instruction that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
    OVERFLOW anchor, so it cannot see one.  This is the interior witness, and
    [LapCertGlueLift.fire_via_int_lift] carries it to every anchor. *)
Lemma firei_0RB1RD_0LC1RA_1RB1LC_0LD0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm false true l A0_0RB1RD_0LC1RA_1RB1LC_0LD0RB = Some t ->
  forall p j q0, cview p = (j, Some q0) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j q0 E.
  apply (fire_of_run_instr tm Cc false true l A0_0RB1RD_0LC1RA_1RB1LC_0LD0RB p j (Ap_Alph_101_111_11 q0 ++ [S0]) []);
    [exact Hst | discriminate | reflexivity | exact (gsi_0RB1RD_0LC1RA_1RB1LC_0LD0RB p j q0 E)].
Qed.

(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_0RB1RD_0LC1RA_1RB1LC_0LD0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_0RB1RD_0LC1RA_1RB1LC_0LD0RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_0RB1RD_0LC1RA_1RB1LC_0LD0RB t p (pow2 j)).
  - exists (6 * j + 10), (cden [] [] j BB1_0RB1RD_0LC1RA_1RB1LC_0LD0RB). split;
      [| exact (gbo_0RB1RD_0LC1RA_1RB1LC_0LD0RB j)].
    rewrite (gso_0RB1RD_0LC1RA_1RB1LC_0LD0RB p j E).
    exact (srun_sound tm true true chb_0RB1RD_0LC1RA_1RB1LC_0LD0RB B0_0RB1RD_0LC1RA_1RB1LC_0LD0RB BB1_0RB1RD_0LC1RA_1RB1LC_0LD0RB 6 10
             run_boot_0RB1RD_0LC1RA_1RB1LC_0LD0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_0RB1RD_0LC1RA_1RB1LC_0LD0RB xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_0RB1RD_0LC1RA_1RB1LC_0LD0RB j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB1RD_0LC1RA_1RB1LC_0LD0RB : forall t, ~ In t pins_0RB1RD_0LC1RA_1RB1LC_0LD0RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
