(** ** The lap *)

Lemma lap_0RB1RD_0LC1RA_1RB1LC_1LC0RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB1RD_0LC1RA_1RB1LC_1LC0RB p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB1RD_0LC1RA_1RB1LC_1LC0RB B0_0RB1RD_0LC1RA_1RB1LC_1LC0RB B1_0RB1RD_0LC1RA_1RB1LC_1LC0RB 6 24 p j' [] []).
    + exact run_ovf_0RB1RD_0LC1RA_1RB1LC_1LC0RB.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB1RD_0LC1RA_1RB1LC_1LC0RB p j' E).
    + exact (geo_0RB1RD_0LC1RA_1RB1LC_1LC0RB p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_0RB1RD_0LC1RA_1RB1LC_1LC0RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 42.
  assert (H : match csteps tm 42 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 42 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB1RD_0LC1RA_1RB1LC_1LC0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB1RD_0LC1RA_1RB1LC_1LC0RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB1RD_0LC1RA_1RB1LC_1LC0RB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB1RD_0LC1RA_1RB1LC_1LC0RB p j E)].
Qed.


