  exists (10 * j + 12), (cden (Ap_Alph_001_011_0 q0 ++ [S1;S0]) [] j A1_0RB1RD_1LC0RA_1RC1LA_1RB0LD).
  split; [lia|]. split; [| exact (gei_0RB1RD_1LC0RA_1RC1LA_1RB0LD p j q0 E)].
  rewrite (gsi_0RB1RD_1LC0RA_1RC1LA_1RB0LD p j q0 E).
  exact (srun_sound tm false true chi_0RB1RD_1LC0RA_1RC1LA_1RB0LD A0_0RB1RD_1LC0RA_1RC1LA_1RB0LD A1_0RB1RD_1LC0RA_1RC1LA_1RB0LD 10 12
           run_int_0RB1RD_1LC0RA_1RC1LA_1RB0LD (Ap_Alph_001_011_0 q0 ++ [S1;S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
