  unfold Cin_0RB1RD_1LC0RD_1LA1LB_0LB1RA, cden, BE0_0RB1RD_1LC0RD_1LA1LB_0LB1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
