  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. exact lapi_0RB1RD_1LC0RD_1LA1LB_0LB1RA. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB1RD_1LC0RD_1LA1LB_0LB1RA : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB1RD_1LC0RD_1LA1LB_0LB1RA p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_0RB1RD_1LC0RD_1LA1LB_0LB1RA).
    split; [lia|]. split; [| exact (gbo_0RB1RD_1LC0RD_1LA1LB_0LB1RA j)].
    rewrite (gso_0RB1RD_1LC0RD_1LA1LB_0LB1RA p j E).
    exact (srun_sound tm true true chb_0RB1RD_1LC0RD_1LA1LB_0LB1RA B0_0RB1RD_1LC0RD_1LA1LB_0LB1RA BB1_0RB1RD_1LC0RD_1LA1LB_0LB1RA 4 8
             run_boot_0RB1RD_1LC0RD_1LA1LB_0LB1RA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 18), (cden [] [] j B1_0RB1RD_1LC0RD_1LA1LB_0LB1RA).
    split; [| exact (geo_0RB1RD_1LC0RD_1LA1LB_0LB1RA p j E)].
