  apply (fire_of_run_instr tm Cc true true l B0_0RB1RD_1LC0RD_1LA1LB_0LB1RA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB1RD_1LC0RD_1LA1LB_0LB1RA p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_0RB1RD_1LC0RD_1LA1LB_0LB1RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_0RB1RD_1LC0RD_1LA1LB_0LB1RA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_0RB1RD_1LC0RD_1LA1LB_0LB1RA t p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_0RB1RD_1LC0RD_1LA1LB_0LB1RA). split;
      [| exact (gbo_0RB1RD_1LC0RD_1LA1LB_0LB1RA j)].
    rewrite (gso_0RB1RD_1LC0RD_1LA1LB_0LB1RA p j E).
    exact (srun_sound tm true true chb_0RB1RD_1LC0RD_1LA1LB_0LB1RA B0_0RB1RD_1LC0RD_1LA1LB_0LB1RA BB1_0RB1RD_1LC0RD_1LA1LB_0LB1RA 4 8
             run_boot_0RB1RD_1LC0RD_1LA1LB_0LB1RA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_0RB1RD_1LC0RD_1LA1LB_0LB1RA xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_0RB1RD_1LC0RD_1LA1LB_0LB1RA j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB1RD_1LC0RD_1LA1LB_0LB1RA : forall t, ~ In t pins_0RB1RD_1LC0RD_1LA1LB_0LB1RA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_0RB1RD_1LC0RD_1LA1LB_0LB1RA.
  destruct t as [q b]; destruct q, b.
  - (* A0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
