(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_0RB1RD_1LC1RB_0RB0LA_1LD0LC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_0RB1RD_1LC1RB_0RB0LA_1LD0LC.
