Lemma geo_0RB1RD_1LC1RB_0RB0LA_1LD0LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB1RD_1LC1RB_0RB0LA_1LD0LC) = lift (Cc (Pos.succ p)).
