Lemma lapil_0RB1RD_1LC1RB_0RB0LA_1LD0LC : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_0RB1RD_1LC1RB_0RB0LA_1LD0LC p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB1RD_1LC1RB_0RB0LA_1LD0LC : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB1RD_1LC1RB_0RB0LA_1LD0LC p (pow2 j)).
  - exists (6 * j + 9), (cden [] [] j BB1_0RB1RD_1LC1RB_0RB0LA_1LD0LC).
    split; [lia|]. split; [| exact (gbo_0RB1RD_1LC1RB_0RB0LA_1LD0LC j)].
    rewrite (gso_0RB1RD_1LC1RB_0RB0LA_1LD0LC p j E).
    exact (srun_sound tm true true chb_0RB1RD_1LC1RB_0RB0LA_1LD0LC B0_0RB1RD_1LC1RB_0RB0LA_1LD0LC BB1_0RB1RD_1LC1RB_0RB0LA_1LD0LC 6 9
             run_boot_0RB1RD_1LC1RB_0RB0LA_1LD0LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (6 * j + 13), (cden [] [] j B1_0RB1RD_1LC1RB_0RB0LA_1LD0LC).
