(** ** The lap *)

Lemma lap_0RB1RD_1RC0LA_0RD____1LD0LB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
