    apply (lap_of_run tm Cc true true cho_0RB1RD_1RC0LA_0RD____1LD0LB B0_0RB1RD_1RC0LA_0RD____1LD0LB B1_0RB1RD_1RC0LA_0RD____1LD0LB 10 15 p j' [] []).
    + exact run_ovf_0RB1RD_1RC0LA_0RD____1LD0LB.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB1RD_1RC0LA_0RD____1LD0LB p j' E).
    + exact (geo_0RB1RD_1RC0LA_0RD____1LD0LB p j' E).
    + lia.
