(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_0RB1RD_1RC0LD_1LA1RB_1LD0LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0]) [] j A0_0RB1RD_1RC0LD_1LA1RB_1LD0LA.
