Lemma geo_0RB1RD_1RC0LD_1LA1RB_1LD0LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB1RD_1RC0LD_1LA1RB_1LD0LA) = lift (Cc (Pos.succ p)).
