  - destruct (lapi_0RB1RD_1RC0LD_1LA1RB_1LD0LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB1RD_1RC0LD_1LA1RB_1LD0LA B0_0RB1RD_1RC0LD_1LA1RB_1LD0LA B1_0RB1RD_1RC0LD_1LA1RB_1LD0LA 8 16 p j' [] []).
    + exact run_ovf_0RB1RD_1RC0LD_1LA1RB_1LD0LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB1RD_1RC0LD_1LA1RB_1LD0LA p j' E).
    + exact (geo_0RB1RD_1RC0LD_1LA1RB_1LD0LA p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_0RB1RD_1RC0LD_1LA1RB_1LD0LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 9.
  assert (H : match csteps tm 9 c0 with
