    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_0RB1RD_1RC0LD_1RD1RB_1LD0LA : sconf := mkC StB (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition AI1_0RB1RD_1RC0LD_1RD1RB_1LD0LA : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [S0] [] 0 0 []).
Definition chn_0RB1RD_1RC0LD_1RD1RB_1LD0LA : list lstep := [SCycL 2 0; SWin 6; SCycR 6; SWinR 2].

Lemma run_inner_0RB1RD_1RC0LD_1RD1RB_1LD0LA : srun tm false true chn_0RB1RD_1RC0LD_1RD1RB_1LD0LA AI0_0RB1RD_1RC0LD_1RD1RB_1LD0LA = Some (AI1_0RB1RD_1RC0LD_1RD1RB_1LD0LA, 8, 8).
