(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_0RB1RD_1RC0LD_1RD1RB_1LD0LA : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S0;S0]) S0 (mkS [S0] [] 0 0 []).
Definition chb_0RB1RD_1RC0LD_1RD1RB_1LD0LA : list lstep := [SCycL 2 0; SWin 6; SCycR 6; SWinR 2].

Lemma run_boot_0RB1RD_1RC0LD_1RD1RB_1LD0LA : srun tm true true chb_0RB1RD_1RC0LD_1RD1RB_1LD0LA B0_0RB1RD_1RC0LD_1RD1RB_1LD0LA = Some (BB1_0RB1RD_1RC0LD_1RD1RB_1LD0LA, 8, 8).
