(** ** The lap *)

Lemma lap_0RB1RD_1RC0LD_1RD1RB_1LD0LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
