    exact (srun_sound tm true true chb_0RB1RD_1RC0LD_1RD1RB_1LD0LA B0_0RB1RD_1RC0LD_1RD1RB_1LD0LA BB1_0RB1RD_1RC0LD_1RD1RB_1LD0LA 8 8
             run_boot_0RB1RD_1RC0LD_1RD1RB_1LD0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_0RB1RD_1RC0LD_1RD1RB_1LD0LA xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_0RB1RD_1RC0LD_1RD1RB_1LD0LA j)].
