    apply (fireo_0RB1RD_1RC0LD_1RD1RB_1LD0LA [SCycL 2 0; SWin 6; SCycR 6; SWinR 1] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
