(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_0RB1RD_1RC0RC_1LD1RA_1LA0LD : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_000_100_1 q0 ++ [S0]) [] 0 Z0_0RB1RD_1RC0RC_1LD1RA_1LA0LD /\
  lift (cden (Ap_Alph_000_100_1 q0 ++ [S0]) [] 0 Z1_0RB1RD_1RC0RC_1LD1RA_1LA0LD) = lift (Cc (Pos.succ p)).
Proof.
  intros p q0 E. destruct (Alph_000_100_1.cview_some_Alph_000_100_1 p 0 q0 E) as (H1 & H2).
  unfold Cc_0RB1RD_1RC0RC_1LD1RA_1LA0LD, cden, Z0_0RB1RD_1RC0RC_1LD1RA_1LA0LD, Z1_0RB1RD_1RC0RC_1LD1RA_1LA0LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - cbn [rep app Nat.mul Nat.add]; rewrite ?app_nil_r.
    change ([S0]) with (([]) ++ [S0]).
    rewrite !lift_app_blank.
    rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_0RB1RD_1RC0RC_1LD1RA_1LA0LD : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_000_100_1 q0 ++ [S0]) [] j P0_0RB1RD_1RC0RC_1LD1RA_1LA0LD /\
  lift (cden (Ap_Alph_000_100_1 q0 ++ [S0]) [] j P1_0RB1RD_1RC0RC_1LD1RA_1LA0LD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (Alph_000_100_1.cview_some_Alph_000_100_1 p (S j) q0 E) as (H1 & H2).
  unfold Cc_0RB1RD_1RC0RC_1LD1RA_1LA0LD, cden, P0_0RB1RD_1RC0RC_1LD1RA_1LA0LD, P1_0RB1RD_1RC0RC_1LD1RA_1LA0LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - cbn [rep app Nat.mul Nat.add]; rewrite ?app_nil_r.
    change ([S0]) with (([]) ++ [S0]).
    rewrite !lift_app_blank.
    rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB1RD_1RC0RC_1LD1RA_1LA0LD : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_0RB1RD_1RC0RC_1LD1RA_1LA0LD p q0 E) as (HA & HB).
    exists (0 * 0 + 4), (cden (Ap_Alph_000_100_1 q0 ++ [S0]) [] 0 Z1_0RB1RD_1RC0RC_1LD1RA_1LA0LD).
    split; [lia|]. split; [| exact HB].
    rewrite HA.
    exact (srun_sound tm false true chz_0RB1RD_1RC0RC_1LD1RA_1LA0LD Z0_0RB1RD_1RC0RC_1LD1RA_1LA0LD Z1_0RB1RD_1RC0RC_1LD1RA_1LA0LD 0 4
             run_z_0RB1RD_1RC0RC_1LD1RA_1LA0LD (Ap_Alph_000_100_1 q0 ++ [S0]) [] 0
             ltac:(discriminate) ltac:(reflexivity)).
  - destruct (gp_0RB1RD_1RC0RC_1LD1RA_1LA0LD p j' q0 E) as (HA & HB).
    exists (8 * j' + 12), (cden (Ap_Alph_000_100_1 q0 ++ [S0]) [] j' P1_0RB1RD_1RC0RC_1LD1RA_1LA0LD).
    split; [lia|]. split; [| exact HB].
    rewrite HA.
    exact (srun_sound tm false true chp_0RB1RD_1RC0RC_1LD1RA_1LA0LD P0_0RB1RD_1RC0RC_1LD1RA_1LA0LD P1_0RB1RD_1RC0RC_1LD1RA_1LA0LD 8 12
             run_p_0RB1RD_1RC0RC_1LD1RA_1LA0LD (Ap_Alph_000_100_1 q0 ++ [S0]) [] j'
             ltac:(discriminate) ltac:(reflexivity)).
Qed.

