Lemma geo_0RB1RD_1RC0RC_1LD1RA_1LA0LD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB1RD_1RC0RC_1LD1RA_1LA0LD) = lift (Cc (Pos.succ p)).
