    apply (lap_of_run tm Cc true true cho_0RB1RD_1RC0RC_1LD1RA_1LA0LD B0_0RB1RD_1RC0RC_1LD1RA_1LA0LD B1_0RB1RD_1RC0RC_1LD1RA_1LA0LD 8 12 p j' [] []).
